=update flow.sync_runs
   set finished_at = now(),
       ok = true,
       detail = jsonb_build_object(
         'statuses_seen', {{ $json.data.length }},
         'statuses_new',  {{ $json.data.filter(function (r) { return r.is_new; }).length }},
         'decision_queue_statuses', {{ $json.data.filter(function (r) { return r.is_decision_queue; }).length }}
       )
 where run_id = {{ $('Start Run').first().json.run_id }};
